CREATE TABLE IF NOT EXISTS project_contexts (id BIGSERIAL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, context_type TEXT NOT NULL, label TEXT NOT NULL, scope_value TEXT, config JSONB NOT NULL DEFAULT '{}'::jsonb, source_summary JSONB NOT NULL DEFAULT '[]'::jsonb, status TEXT NOT NULL DEFAULT 'planned', last_refreshed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now())